import java.util.*;

class Solution {
    public String finalString(String s) {
        Deque<Character> deque = new ArrayDeque<>();
        boolean reversed = false;

        for (int index = 0; index < s.length(); index++) {
            char c = s.charAt(index);
            if (c == 'i') {
                reversed = !reversed;
            } else if (reversed) {
                deque.addFirst(c);
            } else {
                deque.addLast(c);
            }
        }

        StringBuilder answer = new StringBuilder();
        if (!reversed) {
            while (!deque.isEmpty()) {
                answer.append(deque.removeFirst());
            }
        } else {
            while (!deque.isEmpty()) {
                answer.append(deque.removeLast());
            }
        }
        return answer.toString();
    }
}

class Solution {
    public String finalString(String s) {
        StringBuilder front = new StringBuilder();
        StringBuilder back = new StringBuilder();
        boolean reversed = false;

        for (int index = 0; index < s.length(); index++) {
            char c = s.charAt(index);
            if (c == 'i') {
                reversed = !reversed;
            } else if (reversed) {
                front.append(c);
            } else {
                back.append(c);
            }
        }

        if (!reversed) {
            return front.reverse().append(back).toString();
        }
        return back.reverse().append(front).toString();
    }
}

import java.util.*;

class Solution {
    public String finalString(String s) {
        Deque<String> blocks = new ArrayDeque<>();
        StringBuilder run = new StringBuilder();
        boolean reversed = false;

        for (int index = 0; index < s.length(); index++) {
            char c = s.charAt(index);
            if (c == 'i') {
                flushRun(blocks, run, reversed);
                reversed = !reversed;
            } else {
                run.append(c);
            }
        }
        flushRun(blocks, run, reversed);

        StringBuilder answer = new StringBuilder();
        if (!reversed) {
            for (String block : blocks) {
                answer.append(block);
            }
        } else {
            Iterator<String> iterator = blocks.descendingIterator();
            while (iterator.hasNext()) {
                answer.append(new StringBuilder(iterator.next()).reverse());
            }
        }
        return answer.toString();
    }

    private void flushRun(Deque<String> blocks, StringBuilder run, boolean reversed) {
        if (run.length() == 0) {
            return;
        }
        if (reversed) {
            blocks.addFirst(run.reverse().toString());
        } else {
            blocks.addLast(run.toString());
        }
        run.setLength(0);
    }
}
